using System;using System.Collections.Generic;using System.Linq;using UnityEngine;
namespace Groundworks.FuelFire {
public enum FluidKind {Fuel,Oxidizer,Inert}
public class FuelProfile {public string name;public FluidKind kind;public bool gas,selfContained;public Color spray=new Color(.75f,.78f,.72f,.7f),flame=new Color(1,.38f,.06f,1);public float smoke=1;public double oxidizerRatio=11.0/9,ignitionTemperature=550,burnMultiplier=1;}
public static class FuelProfiles {
 static Dictionary<string,FuelProfile> profiles;public static FuelProfile Find(string name){if(profiles==null)Load();FuelProfile p;return profiles.TryGetValue(name,out p)?p:null;}
 static void Add(string names,FluidKind kind,bool gas,bool self,Color flame,float smoke){foreach(string name in names.Split(','))profiles[name]=new FuelProfile{name=name,kind=kind,gas=gas,selfContained=self,flame=flame,smoke=smoke};}
 public static void Load(){profiles=new Dictionary<string,FuelProfile>(StringComparer.OrdinalIgnoreCase);Add("LiquidFuel,Kerosene,RP-1,LqdMethane,Methane,GWMethane,GWDiesel,Diesel",FluidKind.Fuel,false,false,new Color(1,.36f,.05f,1),1);Add("LqdHydrogen,Hydrogen,GWHydrogen",FluidKind.Fuel,true,false,new Color(.25f,.55f,1,1),.08f);Add("MonoPropellant",FluidKind.Fuel,false,true,new Color(1,.65f,.28f,1),.3f);Add("Oxidizer,LqdOxygen,Oxygen,GWOxygen",FluidKind.Oxidizer,false,false,Color.white,0);Add("Water,WasteWater,GWWater,GWWasteWater",FluidKind.Inert,false,false,Color.white,0);Add("LqdNitrogen,Nitrogen,Helium,GWHelium,XenonGas,ArgonGas,IntakeAir",FluidKind.Inert,true,false,Color.white,0);
 if(GameDatabase.Instance==null)return;foreach(var n in GameDatabase.Instance.GetConfigNodes("GROUNDWORKS_FLUID"))FuelRules.ConfigureProfile(n,profiles);}

}
public class FluidSlot {public string name;public FuelProfile profile;public double amount,capacity,density,cloud,rate;public double Mass{get{return amount*density*1000;}}}
public class FuelReservoir {
 public readonly List<FluidSlot> slots=new List<FluidSlot>();public bool Burning;public double LeakedKg,BurnedFuelKg,BurnedOxKg,DispersedKg,LastLeakKgS,LastFuelKgS,LastBurnKgS,LastInertKgS;public Color FlameColor=new Color(1,.38f,.06f),SprayColor=new Color(.75f,.78f,.72f,.7f);public float Smoke=1;public double LiquidRemainingKg{get{return slots.Sum(x=>x.Mass);}}public double CloudKg{get{return slots.Sum(x=>x.cloud);}}
 public void Step(double dt,double severity,bool oxygen,bool ignition,bool burst){Step(dt,severity,oxygen,ignition,burst,true);}
 public void Step(double dt,double severity,bool oxygen,bool ignition,bool burst,bool fireEnabled){Step(dt,severity,oxygen,ignition,burst,fireEnabled,1);}
 public void Step(double dt,double severity,bool oxygen,bool ignition,bool burst,bool fireEnabled,double leakMultiplier){LastLeakKgS=LastFuelKgS=LastBurnKgS=LastInertKgS=0;foreach(var item in slots)item.rate=0;if(!FuelRules.Finite(dt)||dt<=0||dt>1||!FuelRules.Finite(severity))return;severity=Math.Max(0,Math.Min(1,severity));leakMultiplier=FuelRules.Finite(leakMultiplier)?Math.Max(0,Math.Min(10,leakMultiplier)):0;double leaked=0,fuel=0,inert=0;Color spray=Color.clear;foreach(var s in slots){s.rate=0;s.amount=FuelRules.Positive(s.amount);s.cloud=FuelRules.Positive(s.cloud);if(!FuelRules.Finite(s.density)||!FuelRules.Finite(s.capacity)||s.density<=0||s.capacity<=0||s.amount<=0||severity<=0)continue;double fill=Math.Max(0,Math.Min(1,s.amount/s.capacity));double rate=s.capacity*(burst?.12:(.001+.024*Math.Min(1,severity)))*Math.Sqrt(fill)*leakMultiplier;double lost=Math.Min(s.amount,rate*dt);s.amount=Math.Max(0,s.amount-lost);double kg=lost*s.density*1000;s.rate=kg/dt;LeakedKg+=kg;leaked+=kg;spray+=s.profile.spray*(float)kg;if(s.profile.kind==FluidKind.Inert){DispersedKg+=kg;inert+=kg;}else{s.cloud+=kg;if(s.profile.kind==FluidKind.Fuel)fuel+=kg;}}
 LastLeakKgS=leaked/dt;LastFuelKgS=fuel/dt;LastInertKgS=inert/dt;if(leaked>1e-9)SprayColor=spray/(float)leaked;double ox=slots.Where(x=>x.profile.kind==FluidKind.Oxidizer).Sum(x=>x.cloud);bool available=slots.Any(x=>x.profile.kind==FluidKind.Fuel&&x.cloud>1e-7&&(oxygen||x.profile.selfContained||ox>1e-7));if(!fireEnabled)Burning=false;else if(!Burning&&ignition&&available)Burning=true;double burned=0;Color color=Color.black;double smoke=0;
 if(Burning)foreach(var s in slots.Where(x=>x.profile.kind==FluidKind.Fuel&&x.cloud>0)){double desired=Math.Min(s.cloud,Math.Max(s.rate*1.5,s.cloud*.4)*dt*s.profile.burnMultiplier);bool usesOx=!oxygen&&!s.profile.selfContained;if(usesOx){ox=slots.Where(x=>x.profile.kind==FluidKind.Oxidizer).Sum(x=>x.cloud);desired=Math.Min(desired,ox/s.profile.oxidizerRatio);}if(desired<=0)continue;s.cloud-=desired;BurnedFuelKg+=desired;burned+=desired;color+=s.profile.flame*(float)desired;smoke+=s.profile.smoke*desired;if(usesOx){double need=desired*s.profile.oxidizerRatio;foreach(var o in slots.Where(x=>x.profile.kind==FluidKind.Oxidizer&&x.cloud>0)){double used=Math.Min(o.cloud,need);o.cloud-=used;need-=used;BurnedOxKg+=used;if(need<=1e-10)break;}}}
 LastBurnKgS=burned/dt;if(burned<=1e-9)Burning=false;else{FlameColor=color/(float)burned;FlameColor.a=1;Smoke=(float)(smoke/burned);}double decay=1-Math.Exp(-dt*(oxygen?.12:.03));foreach(var s in slots){double lost=s.cloud*decay;if(s.cloud-lost<1e-7)lost=s.cloud;s.cloud=Math.Max(0,s.cloud-lost);DispersedKg+=lost;}if(CloudKg==0)Burning=false;
 }
 public static float VisualScale(double flow){return !FuelRules.Finite(flow)||flow<=0?0:Mathf.Clamp(.10f+.28f*Mathf.Pow((float)flow,.35f),.10f,5f);}
 public void Save(ConfigNode node){node.AddValue("burning",Burning);node.AddValue("leakedKg",LeakedKg);node.AddValue("burnedFuelKg",BurnedFuelKg);node.AddValue("burnedOxKg",BurnedOxKg);node.AddValue("dispersedKg",DispersedKg);foreach(var s in slots){var n=node.AddNode("FLUID");n.AddValue("name",s.name);n.AddValue("cloudKg",s.cloud);}}
 public void Load(ConfigNode node){if(node==null)return;bool b;if(bool.TryParse(node.GetValue("burning"),out b))Burning=b;LeakedKg=Number(node,"leakedKg");BurnedFuelKg=Number(node,"burnedFuelKg");BurnedOxKg=Number(node,"burnedOxKg");DispersedKg=Number(node,"dispersedKg");foreach(var slot in slots)slot.cloud=0;foreach(var n in node.GetNodes("FLUID")){var s=slots.FirstOrDefault(x=>x.name==n.GetValue("name"));if(s!=null)s.cloud=Number(n,"cloudKg");}}
 static double Number(ConfigNode n,string key){double v;return double.TryParse(n.GetValue(key),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out v)&&!double.IsNaN(v)&&!double.IsInfinity(v)?Math.Max(0,v):0;}
}
}
